    print(ACNode.load(mss.trie.serialize()))

"""Access to the Corkami "pocs" corpus of polyglot and edge-case files.

The corpus is downloaded on demand rather than vendored (``tests/.gitignore`` excludes it), so
importing this module is cheap and has no side effects.
"""

from pathlib import Path
import shutil
from tempfile import TemporaryDirectory
from typing import Iterator
import urllib.request
from zipfile import ZipFile, ZipInfo

CORKAMI_CORPUS_ZIP = Path(__file__).absolute().parent / "corkami.zip"
CORKAMI_URL = "https://github.com/corkami/pocs/archive/refs/heads/master.zip"


class CorkamiFile:
    def __init__(self, path_in_zip: Path, info: ZipInfo):
        self.path_in_zip: Path = path_in_zip
        self.info: ZipInfo = info
        self._tmpdir: TemporaryDirectory = None  # type: ignore

    def __enter__(self) -> Path:
        self._tmpdir = TemporaryDirectory()
        self._tmpdir.__enter__()
        with ZipFile(CORKAMI_CORPUS_ZIP, "r") as z:
            return Path(z.extract(self.info, self._tmpdir.name))

    def __exit__(self, exc_type, exc_val, exc_tb):
        self._tmpdir.__exit__(exc_type, exc_val, exc_tb)


class CorkamiCorpus:
    @classmethod
    def download(cls):
        with urllib.request.urlopen(CORKAMI_URL) as response, open(CORKAMI_CORPUS_ZIP, "wb") as out_file:
            shutil.copyfileobj(response, out_file)

    @classmethod
    def ensure_downloaded(cls):
        if not CORKAMI_CORPUS_ZIP.exists():
            cls.download()

    @classmethod
    def read(cls, path_in_zip: str) -> bytes:
        """Returns the contents of one file in the corpus, downloading the corpus if necessary."""
        cls.ensure_downloaded()
        with ZipFile(CORKAMI_CORPUS_ZIP, "r") as z:
            return z.read(path_in_zip)

    @classmethod
    def files(cls) -> Iterator[CorkamiFile]:
        cls.ensure_downloaded()
        with ZipFile(CORKAMI_CORPUS_ZIP, "r") as z:
            for info in z.infolist():
                if info.is_dir() or info.file_size <= 0:
                    continue
                path = Path(info.filename)
                if not path.name.startswith("."):
                    yield CorkamiFile(path_in_zip=path, info=info)

from pathlib import Path
from typing import Dict, FrozenSet, Set
from unittest import TestCase, skipUnless

POLYFILE_DIR: Path = Path(__file__).absolute().parent.parent
MAGIC_DEFS_DIR: Path = POLYFILE_DIR / "polyfile" / "magic_defs"
UPSTREAM_MAGDIR: Path = POLYFILE_DIR / "file" / "magic" / "Magdir"
UPSTREAM_COPYING: Path = POLYFILE_DIR / "file" / "COPYING"

HAVE_MAGDIR: bool = UPSTREAM_MAGDIR.is_dir() and any(UPSTREAM_MAGDIR.iterdir())

SYNC_DOC: str = "docs/updating_libmagic_defs.md"

IGNORED: FrozenSet[str] = frozenset({"magic.mgc", "__pycache__"})
"""Entries `polyfile.magic.MAGIC_DEFS` skips, so they are neither definitions nor PolyFile's own."""

POLYFILE_OWNED: FrozenSet[str] = frozenset({
    "__init__.py", "COPYING", "csv", "json", "polyfile_zip"
})
"""The entries of `polyfile/magic_defs` that PolyFile writes rather than copies from upstream."""

LOCAL_PATCHES: Dict[str, str] = {
    "c-lang": "https://github.com/trailofbits/polyfile/issues/3411",
    "gentoo": "https://github.com/trailofbits/polyfile/issues/3473",
}
"""Definitions that deliberately differ from upstream, each mapped to the issue that justifies it.

Add an entry only alongside the issue explaining why the patch has to exist, and delete it in the
change that drops the patch. Anything not listed here has to be a byte-for-byte copy of upstream.
"""

PENDING_PATCHES: FrozenSet[str] = frozenset()
"""Allowlist entries whose patch is still in review, so the bundled file still matches upstream.

Naming an entry here disarms the allowlist check for it, which lets a `LOCAL_PATCHES` entry land
before the pull request that patches the definition does. Delete the name once that pull request
merges; `test_shared_definitions_are_byte_identical` fails with that instruction the moment the
patch lands, so the allowlist cannot stay disarmed by accident.
"""


def definition_names(directory: Path) -> Set[str]:
    """Lists the entries of a definition directory that `MAGIC_DEFS` loads as definitions."""
    return {
        entry.name
        for entry in directory.iterdir()
        if entry.name not in IGNORED and not entry.name.startswith(".")
    }


@skipUnless(HAVE_MAGDIR, "the file submodule is not checked out")
class TestMagicDefsDrift(TestCase):
    """Guards the rule that `polyfile/magic_defs` is a copy of the `file` submodule's `Magdir`.

    The copy is maintained by hand and is not append-only in either direction. Definitions upstream
    deletes keep matching until someone notices, and a plain copy of `Magdir` silently reverts the
    local patches. These tests fail on both, and on the third case the allowlist exists for:
    upstream rewriting the lines a local patch touches.
    """

    def setUp(self):
        self.upstream = definition_names(UPSTREAM_MAGDIR)
        self.bundled = definition_names(MAGIC_DEFS_DIR)
        self.assertTrue(self.upstream, f"{UPSTREAM_MAGDIR} holds no definitions")

    def test_every_upstream_definition_is_bundled(self):
        missing = self.upstream - self.bundled
        self.assertEqual(
            set(), missing,
            f"{', '.join(sorted(missing))} is in file/magic/Magdir/ but not in"
            f" polyfile/magic_defs/. Mirror the directory again, as {SYNC_DOC} describes"
        )

    def test_polyfile_s_own_entries_are_all_present(self):
        missing = POLYFILE_OWNED - self.bundled
        self.assertEqual(
            set(), missing,
            f"{', '.join(sorted(missing))} is PolyFile's own and is gone from polyfile/magic_defs/."
            f" A mirror of Magdir has to exclude it, as {SYNC_DOC} describes"
        )

    def test_the_only_extra_entries_are_polyfile_s_own(self):
        extras = self.bundled - self.upstream - POLYFILE_OWNED
        self.assertEqual(
            set(), extras,
            f"{', '.join(sorted(extras))} is in polyfile/magic_defs/ but not in file/magic/Magdir/."
            f" Upstream no longer ships it, so PolyFile matches a definition libmagic has dropped:"
            f" mirror the directory with `rsync -a --delete`, as {SYNC_DOC} describes. If PolyFile"
            f" owns the file, add it to POLYFILE_OWNED instead"
        )

    def test_shared_definitions_are_byte_identical(self):
        allowed_to_differ = set(LOCAL_PATCHES) - PENDING_PATCHES
        for name in sorted((self.upstream & self.bundled) - allowed_to_differ):
            with self.subTest(definition=name):
                if (UPSTREAM_MAGDIR / name).read_bytes() != (MAGIC_DEFS_DIR / name).read_bytes():
                    self.fail(self.drift_message(name))

    def test_local_patches_are_still_applied(self):
        for name, issue in sorted(LOCAL_PATCHES.items()):
            if name in PENDING_PATCHES:
                continue
            with self.subTest(definition=name):
                if (UPSTREAM_MAGDIR / name).read_bytes() == (MAGIC_DEFS_DIR / name).read_bytes():
                    self.fail(
                        f"polyfile/magic_defs/{name} is identical to file/magic/Magdir/{name}, so"
                        f" the patch from {issue} is gone. Mirroring Magdir reverts local patches;"
                        f" re-apply it, as {SYNC_DOC} describes. If upstream has fixed the problem"
                        f" the patch worked around, drop the entry from LOCAL_PATCHES instead"
                    )

    def test_copying_matches_upstream(self):
        if UPSTREAM_COPYING.read_bytes() != (MAGIC_DEFS_DIR / "COPYING").read_bytes():
            self.fail(
                "polyfile/magic_defs/COPYING is not the license the definitions ship under."
                " Copy it again: `cp file/COPYING polyfile/magic_defs/COPYING`"
            )

    @staticmethod
    def drift_message(name: str) -> str:
        """Explains one definition's disagreement with upstream, and what to do about it."""
        if name in PENDING_PATCHES:
            return (
                f"polyfile/magic_defs/{name} now carries the patch from {LOCAL_PATCHES[name]}."
                f" Delete {name!r} from PENDING_PATCHES, which arms the allowlist check that keeps"
                f" the patch from being reverted"
            )
        return (
            f"polyfile/magic_defs/{name} differs from file/magic/Magdir/{name}. If this is a"
            f" deliberate local patch, add it to LOCAL_PATCHES along with the issue that justifies"
            f" it; otherwise copy the definition again, as {SYNC_DOC} describes"
        )

import random
from typing import Iterator
from unittest import TestCase

from polyfile.iterators import LazyIterableSequence, LazyIterableSet, unique


class TestIterators(TestCase):
    @staticmethod
    def random_sequence(min_len: int = 0, max_len: int = 1000) -> Iterator[str]:
        seq_length = random.randint(min_len, max_len)
        for _ in range(seq_length):
            yield chr(random.randint(ord('a'), ord('z')))

    def test_lazy_sequence(self):
        for _ in range(100):
            ground_truth = list(TestIterators.random_sequence())
            seq = LazyIterableSequence(ground_truth)
            seq_iter = iter(seq)
            if len(ground_truth) > 0:
                self.assertEqual(next(seq_iter), ground_truth[0])
            for i, s in enumerate(seq):
                self.assertEqual(ground_truth[i], s)
            self.assertEqual("".join(ground_truth), "".join(seq))
            if len(ground_truth) > 1:
                self.assertEqual(next(seq_iter), ground_truth[1])

    def test_lazy_set(self):
        for _ in range(100):
            ground_truth = list(TestIterators.random_sequence())
            seq = LazyIterableSet(ground_truth)
            self.assertEqual("".join(unique(ground_truth)), "".join(seq))

import json
from pathlib import Path
from typing import Set
from unittest import TestCase, skipUnless

from compile_kaitai_parsers import KAITAI_FORMAT_LIBRARY, MANIFEST_PATH, excluded_specs, spec_license

POLYFILE_DIR: Path = Path(__file__).absolute().parent.parent
MANIFEST_IN_PATH: Path = POLYFILE_DIR / "MANIFEST.in"
PARSERS_DIR: Path = MANIFEST_PATH.parent

HAVE_FORMAT_LIBRARY: bool = KAITAI_FORMAT_LIBRARY.is_dir() and any(KAITAI_FORMAT_LIBRARY.glob("**/*.ksy"))


def manifest_in_exclusions() -> Set[str]:
    """Reads the specifications that MANIFEST.in keeps out of the source distribution."""
    prefix = "exclude kaitai_struct_formats/"
    return {
        line[len(prefix):].strip()
        for line in MANIFEST_IN_PATH.read_text().splitlines()
        if line.startswith(prefix)
    }


@skipUnless(HAVE_FORMAT_LIBRARY, "the kaitai_struct_formats submodule is not checked out")
class TestKaitaiLicensing(TestCase):
    """Guards the rule that PolyFile only redistributes permissively licensed Kaitai specifications.

    A parser generated by the Kaitai Struct compiler is a derivative work of the specification it
    was generated from, so shipping one built from a copyleft specification would put the Apache 2.0
    distribution out of compliance. These tests fail if such a parser reaches the package, or if the
    source distribution stops agreeing with the compiler about which specifications are excluded.
    """

    def setUp(self):
        self.excluded = excluded_specs()
        self.assertTrue(self.excluded, "expected at least one non-permissive specification")

    def test_manifest_lists_only_permissive_specs(self):
        with open(MANIFEST_PATH, "r") as f:
            manifest = json.load(f)
        for relative_path in manifest:
            with self.subTest(spec=relative_path):
                self.assertIsNotNone(
                    spec_license(KAITAI_FORMAT_LIBRARY / relative_path),
                    f"{relative_path} is in the parser manifest but declares no license"
                )
                self.assertNotIn(KAITAI_FORMAT_LIBRARY / relative_path, self.excluded)

    def test_no_parser_is_generated_from_an_excluded_spec(self):
        generated = {path.stem for path in PARSERS_DIR.glob("*.py")}
        for spec, license_name in self.excluded.items():
            with self.subTest(spec=str(spec.relative_to(KAITAI_FORMAT_LIBRARY))):
                self.assertNotIn(
                    spec.stem, generated,
                    f"{spec.stem}.py is generated from {spec.name}, which is licensed "
                    f"{license_name or 'not at all'}"
                )

    def test_source_distribution_excludes_the_same_specs(self):
        expected = {str(spec.relative_to(KAITAI_FORMAT_LIBRARY)) for spec in self.excluded}
        self.assertEqual(
            expected, manifest_in_exclusions(),
            "MANIFEST.in and compile_kaitai_parsers.excluded_specs() disagree about which "
            "specifications PolyFile may redistribute"
        )
